use anyhow::{ensure,Context};
struct SqliteUnpublishedView{metadata:Option<serde_json::Value>,content:Option<serde_json::Value>,draft_id:String,raw_draft:serde_json::Value}
struct SqliteUnpublishedPage{space:String,id:String,owner:SqliteUnpublishedView,samples:Vec<SqliteUnpublishedView>}
struct OriginalUnpublishedPlan{root:Identity,database:Identity,actor:String,session:String,pages:Vec<SqliteUnpublishedPage>}
async fn sqlite_unpublished_view(original:&mut StoppedVerificationSource<'_>,auth:&crate::auth::middleware::AuthUser,space:&str,id:&str,base:&serde_json::Value)->anyhow::Result<SqliteUnpublishedView>{
 let selected=verification_expected_access(crate::spaces::documents::readable_discovery_draft(original.conn,auth,space,id).await)?;
 let Some(draft)=selected else{return Ok(SqliteUnpublishedView{metadata:None,content:None,draft_id:String::new(),raw_draft:serde_json::Value::Null})};
 let principal=crate::spaces::access::principal_from_auth(auth).map_err(|_|fail("Original unpublished actor expired"))?;
 let metadata_allowed=verification_expected_access(crate::spaces::access::resolve_page_access(original.conn,principal,space,id,crate::spaces::access::PageOperation::InspectMetadata,crate::spaces::access::Purpose::Routine).await)?.is_some();
 let principal=crate::spaces::access::principal_from_auth(auth).map_err(|_|fail("Original unpublished actor expired"))?;
 let content_allowed=verification_expected_access(crate::spaces::access::resolve_page_access(original.conn,principal,space,id,crate::spaces::access::PageOperation::View,crate::spaces::access::Purpose::Routine).await)?.is_some();
 let content=if content_allowed{Some(serde_json::json!({"id":id,"title":draft.title,"content":crate::spaces::documents::discovery_draft_content(&draft).map_err(|e|anyhow::anyhow!("Original selected draft projection unavailable:{e:?}"))?}))}else{None};
 let metadata=if metadata_allowed{let mut value=base.clone();value["title"]=draft.title.clone().into();value["icon"]=serde_json::to_value(&draft.icon)?;value["cover_image"]=serde_json::to_value(&draft.cover_image)?;value["draft_id"]=draft.id.clone().into();value["identifier_edit_allowed"]=crate::spaces::page_metadata::edit_allowed(original.conn,auth,space,id).await.map_err(|e|anyhow::anyhow!("Original draft identifier capability unavailable:{e:?}"))?.into();value["maintenance_edit_allowed"]=crate::spaces::maintenance::edit_allowed(original.conn,auth,space,id).await.map_err(|e|anyhow::anyhow!("Original draft maintenance capability unavailable:{e:?}"))?.into();Some(value)}else{None};
 let rows=crate::spaces::document_deletion::rows(original.conn,"SELECT * FROM document_drafts WHERE id=$1 AND space_id=$2 AND document_id=$3",&[&draft.id,space,id]).await.map_err(|e|anyhow::anyhow!(e))?;ensure!(rows.len()==1,"Original selected draft raw identity absent");let raw_draft=serde_json::to_value(&rows)?;ensure!(serde_json::to_vec(&raw_draft)?.len()<=8*1024*1024,"Original selected raw draft exceeds8MiB");
 Ok(SqliteUnpublishedView{metadata,content,draft_id:draft.id,raw_draft})
}
impl OriginalUnpublishedPlan{
 async fn capture(original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,audiences:Option<&OriginalApplicationAudiences<'_>>)->anyhow::Result<Self>{
 use sqlx::Row;original.fence().await?;published.fence(original)?;drafts.fence(original)?;if let Some(a)=audiences{a.fence(original,published,drafts).await?;}let rows=sqlx::query("SELECT id,space_id,created_at,updated_at FROM documents WHERE published_at IS NULL AND archived_at IS NULL AND deleted_at IS NULL ORDER BY space_id,id LIMIT 257").fetch_all(&mut *original.conn).await?;ensure!(published.pages.len().checked_add(rows.len()).is_some_and(|n|n<=256),"Complete SQLite application plan exceeds256 active published/unpublished pages");
 let admin=original.admin.context("Original unpublished human absent")?;let auth=crate::auth::middleware::AuthUser{claims:admin.claims.clone(),api_key_scopes:None};let mut pages=Vec::new();let mut total=0usize;
 for row in rows{let id:String=row.try_get("id")?;let space:String=row.try_get("space_id")?;let base=serde_json::json!({"id":id,"space_id":space,"created_at":row.try_get::<String,_>("created_at")?,"updated_at":row.try_get::<String,_>("updated_at")?,"published_at":null});let owner=sqlite_unpublished_view(original,&auth,&space,&id,&base).await?;ensure!(owner.metadata.is_some()&&owner.content.is_some(),"Original SQLite administrator cannot certify selected unpublished discovery");let mut samples=Vec::new();for sample in audiences.into_iter().flat_map(|a|a.samples.iter()){samples.push(sqlite_unpublished_view(original,&sample.credential.auth,&space,&id,&base).await?);}for view in std::iter::once(&owner).chain(samples.iter()){let size=serde_json::to_vec(&serde_json::json!({"metadata":view.metadata,"content":view.content,"draft":view.raw_draft}))?.len();total=total.checked_add(size).context("Original SQLite unpublished plan overflow")?;ensure!(total<=16*1024*1024,"Original SQLite unpublished plan exceeds16MiB");}pages.push(SqliteUnpublishedPage{space,id,owner,samples});}
 let plan=Self{root:original.root_identity()?,database:identity(original.database)?,actor:admin.claims.sub.clone(),session:admin.claims.sid.clone(),pages};plan.fence(original,published,drafts,audiences).await?;Ok(plan)
 }
 async fn fence(&self,original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,audiences:Option<&OriginalApplicationAudiences<'_>>)->anyhow::Result<()>{original.fence().await?;published.fence(original)?;drafts.fence(original)?;if let Some(a)=audiences{a.fence(original,published,drafts).await?;}let admin=original.admin.context("Original unpublished human absent")?;ensure!(self.root==original.root_identity()?&&self.database==identity(original.database)?&&self.actor==admin.claims.sub&&self.session==admin.claims.sid,"Original SQLite unpublished source context differs");for page in &self.pages{ensure!(page.samples.len()==audiences.map(|a|a.samples.len()).unwrap_or(0),"Original SQLite unpublished audience closure differs");for view in std::iter::once(&page.owner).chain(page.samples.iter()){if !view.draft_id.is_empty(){let rows=crate::spaces::document_deletion::rows(original.conn,"SELECT * FROM document_drafts WHERE id=$1 AND space_id=$2 AND document_id=$3",&[&view.draft_id,&page.space,&page.id]).await.map_err(|e|anyhow::anyhow!(e))?;ensure!(serde_json::to_value(rows)?==view.raw_draft,"Original SQLite unpublished draft identity/bytes/digest differ");}}}original.fence().await?;Ok(())}
}
fn sqlite_verify_unpublished_reply(expected:Option<&serde_json::Value>,status:reqwest::StatusCode,actual:&serde_json::Value,metadata:bool)->anyhow::Result<()>{if let Some(expected)=expected{ensure!(status==reqwest::StatusCode::OK,"Original permitted SQLite unpublished route refused");if metadata{for(key,value)in expected.as_object().context("Original SQLite unpublished metadata malformed")?{ensure!(actual.get(key)==Some(value),"Original SQLite unpublished metadata/draft/capability differs");}}else{ensure!(actual==expected&&actual.get("published_source_digest").is_none()&&actual.get("published_metadata").is_none(),"Original selected SQLite unpublished body/presentation/publication fields differ");}}else{ensure!(matches!(status.as_u16(),401|403|404),"Original denied SQLite unpublished audience received discovery state");}Ok(())}
async fn sqlite_unpublished_observation<T>(original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,assets:&OriginalApplicationAssets<'_>,audiences:Option<&OriginalApplicationAudiences<'_>>,process:&mut std::process::Child,channel:&File,nonce:&str,work:impl std::future::Future<Output=anyhow::Result<T>>)->anyhow::Result<T>{ensure!(process.try_wait()?.is_none(),"Actual SQLite worker exited before unpublished observation");let result=if let Some(a)=audiences{normal_audience_observation(original,published,drafts,a,assets,process,channel,nonce,work).await}else{normal_source_fenced_observation(original,published,channel,nonce,work).await};ensure!(process.try_wait()?.is_none(),"Actual SQLite worker exited during unpublished observation");result}
async fn verify_normal_sqlite_unpublished(original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,assets:&OriginalApplicationAssets<'_>,plan:&OriginalUnpublishedPlan,audiences:Option<&OriginalApplicationAudiences<'_>>,process:&mut std::process::Child,address:std::net::SocketAddr,token:&str,channel:&File,nonce:&str)->anyhow::Result<()>{plan.fence(original,published,drafts,audiences).await?;let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(120)).redirect(reqwest::redirect::Policy::none()).no_proxy().build()?;for page in &plan.pages{let prefix=format!("/spaces/{}/documents/{}",urlencoding::encode(&page.space),urlencoding::encode(&page.id));for(suffix,metadata)in [("",true),("/content",false)]{let uri=format!("{prefix}{suffix}");let(status,value)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,Some(token),&uri)).await?;sqlite_verify_unpublished_reply(if metadata{page.owner.metadata.as_ref()}else{page.owner.content.as_ref()},status,&value,metadata)?;for(sample,view)in audiences.into_iter().flat_map(|a|a.samples.iter()).zip(&page.samples){let(status,value)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,Some(&sample.credential.bearer),&uri)).await?;sqlite_verify_unpublished_reply(if metadata{view.metadata.as_ref()}else{view.content.as_ref()},status,&value,metadata)?;}let(status,value)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,None,&uri)).await?;sqlite_verify_unpublished_reply(None,status,&value,metadata)?;}}plan.fence(original,published,drafts,audiences).await?;Ok(())}
async fn verify_normal_sqlite_preindex_private(original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,assets:&OriginalApplicationAssets<'_>,audiences:Option<&OriginalApplicationAudiences<'_>>,process:&mut std::process::Child,address:std::net::SocketAddr,token:&str,channel:&File,nonce:&str)->anyhow::Result<()>{let words=normal_original_private_words(published,drafts)?;ensure!(drafts.drafts.is_empty()||!words.is_empty(),"Original SQLite draft lacks distinguishing pre-index term");let admin=original.admin.context("Original SQLite private search human absent")?;let auth=crate::auth::middleware::AuthUser{claims:admin.claims.clone(),api_key_scopes:None};let owner=verification_expected_access(crate::spaces::access::require_current_human_read(original.conn,&auth).await)?.is_some();let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(120)).redirect(reqwest::redirect::Policy::none()).no_proxy().build()?;for word in &words{sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_private_default_search(&client,address,token,word,owner)).await?;for sample in audiences.into_iter().flat_map(|a|a.samples.iter()){sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_private_default_search(&client,address,&sample.credential.bearer,word,sample.expected.global_read)).await?;}let uri=format!("/search?q={}&limit=100",urlencoding::encode(word));let(status,_)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,None,&uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous SQLite search exposed private draft state");}Ok(())}
#[cfg(test)]mod sqlite_unpublished_controls{use super::*;#[test]fn original_draft_projection_and_denials_are_exact(){let expected=serde_json::json!({"id":"original","title":"Selected draft","content":"Original draft"});assert!(sqlite_verify_unpublished_reply(Some(&expected),reqwest::StatusCode::OK,&expected,false).is_ok());for key in ["id","content","published_metadata","published_source_digest"]{let mut wrong=expected.clone();wrong[key]="foreign".into();assert!(sqlite_verify_unpublished_reply(Some(&expected),reqwest::StatusCode::OK,&wrong,false).is_err());}assert!(sqlite_verify_unpublished_reply(None,reqwest::StatusCode::OK,&expected,false).is_err());assert!(sqlite_verify_unpublished_reply(None,reqwest::StatusCode::NOT_FOUND,&serde_json::Value::Null,false).is_ok());}}

// An exact empty original plan still exercises registered current-user search
// and anonymous denial after the registered rebuild has asserted indexed=0.
async fn verify_normal_sqlite_empty_search(original:&mut StoppedVerificationSource<'_>,published:&OriginalApplicationPlan<'_>,drafts:&OriginalApplicationDraftPlan<'_>,assets:&OriginalApplicationAssets<'_>,unpublished:&OriginalUnpublishedPlan,audiences:Option<&OriginalApplicationAudiences<'_>>,process:&mut std::process::Child,address:std::net::SocketAddr,token:&str,channel:&File,nonce:&str)->anyhow::Result<()>{
 if !published.pages.is_empty()||!unpublished.pages.is_empty(){return Ok(());}
 unpublished.fence(original,published,drafts,audiences).await?;
 let client=reqwest::Client::builder().timeout(std::time::Duration::from_secs(120)).redirect(reqwest::redirect::Policy::none()).no_proxy().build()?;
 let uri="/search?q=EMPTYORIGINALWORKSPACE&limit=100";
 for credential in std::iter::once(token).chain(audiences.into_iter().flat_map(|a|a.samples.iter().map(|s|s.credential.bearer.as_str()))){
  let(status,value)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,Some(credential),uri)).await?;
  ensure!(status==reqwest::StatusCode::OK&&value.as_array().is_some_and(|v|v.is_empty()),"Exact empty original workspace returned search data or lost current-human access");
 }
 let(status,_)=sqlite_unpublished_observation(original,published,drafts,assets,audiences,process,channel,nonce,normal_tcp_json(&client,address,None,uri)).await?;
 ensure!(matches!(status.as_u16(),401|403|404),"Anonymous empty-workspace search acquired access");
 unpublished.fence(original,published,drafts,audiences).await?;Ok(())
}
